cd /app && python3 -c "
import json
with open('agents/coach/workspace/experiments.jsonl') as f:
    lines = f.readlines()

decisions = {}
agents_count = {}
total = 0
for line in lines:
    try:
        d = json.loads(line.strip())
        # Check various formats
        decision = d.get('decision', '')
        result = d.get('result', '')
        if isinstance(result, dict):
            decision = result.get('decision', decision)
        if not decision:
            if 'discard' in str(result).lower():
                decision = 'discard'
            elif 'promote' in str(result).lower():
                decision = 'promote'
            elif 'PENDING' in str(result):
                decision = 'pending'
            else:
                decision = str(result)[:20] if result else 'unknown'
        decisions[decision] = decisions.get(decision, 0) + 1

        agent = d.get('agent', '?')
        agents_count[agent] = agents_count.get(agent, 0) + 1
        total += 1
    except:
        pass

print(f'Total experiment entries: {total}')
print()
print('By decision:')
for k in sorted(decisions, key=lambda x: decisions[x], reverse=True):
    print(f'  {k}: {decisions[k]}')
print()
print('By agent:')
for k in sorted(agents_count, key=lambda x: agents_count[x], reverse=True):
    print(f'  {k}: {agents_count[k]}')
"

